/bin/bash -lc "cat << 'EOF' > /workspace/openai_client.py
import json
import urllib.request
import urllib.error

class OpenAIClient:
    \"\"\"
    A simple client to send text prompts to OpenAI's Responses API 
    using only the Python standard library.
    \"\"\"
    def __init__(self, api_key: str, base_url: str = \"https://api.openai.com/v1\"):
        self.api_key = api_key
        self.base_url = base_url

    def send_prompt(self, prompt: str, model: str = \"gpt-4o\"):
        url = f\"{self.base_url}/chat/completions\"

        headers = {
            \"Content-Type\": \"application/json\",
            \"Authorization\": f\"Bearer {self.api_key}\"
        }

        data = {
            \"model\": model,
            \"messages\": [{\"role\": \"user\", \"content\": prompt}]
        }

        try:
            req = urllib.request.Request(
                url, 
                data=json.dumps(data).encode(\"utf-8\"), 
                headers=headers, 
                method=\"POST\"
            )
            with urllib.request.urlopen(req) as response:
                return json.loads(response.read().decode(\"utf-8\"))
        except urllib.error.HTTPError as e:
            print(f\"HTTP Error: {e.code} - {e.reason}\")
            return None
        except urllib.error.URLError as e:
            print(f\"URL Error: {e.reason}\")
            return None
        except Exception as e:
            print(f\"An unexpected error occurred: {e}\")
            return None

if __name__ == \"__main__\":
    # Example usage
    import os
    key = os.getenv(\"OPENAI_API_KEY\")
    if key:
        client = OpenAIClient(key)
        result = client.send_prompt(\"Hello, how are you?\")
        print(json.dumps(result, indent=2))
    else:
        print(\"Please set the OPENAI_API_KEY environment variable.\")
EOF
"

